def run_bst(root, values):
    def add(node, key):
        if node is None:
            return TreeNode(key), True
        current = node
        while True:
            if key == current.val:
                return node, False
            if key < current.val:
                if current.left is None:
                    current.left = TreeNode(key)
                    return node, True
                current = current.left
            else:
                if current.right is None:
                    current.right = TreeNode(key)
                    return node, True
                current = current.right
    added = 0
    for key in values[::-1]:
        root, changed = add(root, key)
        added += int(changed)
    return (root, added)
